PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?naicsInst ?naicsCode ?naicsText ?state ?stateLabel ?mfgCount
WHERE {
  {
    SELECT ?naicsInst ?naicsCode ?naicsText ?state ?stateLabel ?mfgCount (1 + COUNT(?mfgCount2) AS ?rank)
    WHERE {
      {
        SELECT ?naicsInst ?naicsCode ?naicsText ?state ?stateLabel (COUNT(DISTINCT ?org) AS ?mfgCount)
        WHERE {
          ?org a iof-core:Manufacturer ;
               sdk:hasPrimaryNAICSClassifier ?naicsInst ;
               sdk:organizationLocatedIn ?site .
          ?site sdk:locatedInCity ?city .
          ?city sdk:locatedInState ?state .
          OPTIONAL { ?state rdfs:label ?stateLabel . }
          OPTIONAL { ?naicsInst sdk:hasNAICSCodeValue ?naicsCode . }
          OPTIONAL { ?naicsInst sdk:hasNAICSTextValue ?naicsText . }
        }
        GROUP BY ?naicsInst ?naicsCode ?naicsText ?state ?stateLabel
      }
      OPTIONAL {
        {
          SELECT ?naicsInst2 ?state2 (COUNT(DISTINCT ?org2) AS ?mfgCount2)
          WHERE {
            ?org2 a iof-core:Manufacturer ;
                  sdk:hasPrimaryNAICSClassifier ?naicsInst2 ;
                  sdk:organizationLocatedIn ?site2 .
            ?site2 sdk:locatedInCity ?city2 .
            ?city2 sdk:locatedInState ?state2 .
          }
          GROUP BY ?naicsInst2 ?state2
        }
        FILTER(?naicsInst2 = ?naicsInst && ?mfgCount2 > ?mfgCount)
      }
    }
    GROUP BY ?naicsInst ?naicsCode ?naicsText ?state ?stateLabel ?mfgCount
  }
  FILTER(?rank <= 5)
}
ORDER BY ?naicsInst DESC(?mfgCount) ?stateLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX bfo: <http://purl.obolibrary.org/obo/>

SELECT
  ?manufacturer
  (COALESCE(SAMPLE(?manufacturerLabelRaw), "Unknown") AS ?manufacturerLabel)
  (COALESCE(STR(SAMPLE(?numRaw)), "Unknown") AS ?numberOfEmployees)
  (IF(STRLEN(GROUP_CONCAT(DISTINCT ?certLabel; SEPARATOR=", ")) > 0, GROUP_CONCAT(DISTINCT ?certLabel; SEPARATOR=", "), "Unknown") AS ?certificates)
  (IF(STRLEN(GROUP_CONCAT(DISTINCT ?industryLabel; SEPARATOR=", ")) > 0, GROUP_CONCAT(DISTINCT ?industryLabel; SEPARATOR=", "), "Unknown") AS ?industries)
  (IF(STRLEN(GROUP_CONCAT(DISTINCT ?procLabel; SEPARATOR=", ")) > 0, GROUP_CONCAT(DISTINCT ?procLabel; SEPARATOR=", "), "Unknown") AS ?processCapabilities)
  (IF(STRLEN(GROUP_CONCAT(DISTINCT ?matLabel; SEPARATOR=", ")) > 0, GROUP_CONCAT(DISTINCT ?matLabel; SEPARATOR=", "), "Unknown") AS ?materialCapabilities)
  (COALESCE(STR(SAMPLE(?naicsCodeRaw)), "Unknown") AS ?naicsCode)
  (COALESCE(SAMPLE(?naicsTextRaw), "Unknown") AS ?naicsText)
  (COALESCE(SAMPLE(?cityLabelRaw), "Unknown") AS ?city)
  (COALESCE(SAMPLE(?stateLabelRaw), "Unknown") AS ?state)
  (COALESCE(STR(SAMPLE(?zipRaw)), "Unknown") AS ?zip)
  (COALESCE(SAMPLE(?addressRaw), "Unknown") AS ?address)
  (COALESCE(STR(SAMPLE(?latRaw)), "Unknown") AS ?latitude)
  (COALESCE(STR(SAMPLE(?lonRaw)), "Unknown") AS ?longitude)
  (IF(STRLEN(GROUP_CONCAT(DISTINCT ?productLabel; SEPARATOR=", ")) > 0, GROUP_CONCAT(DISTINCT ?productLabel; SEPARATOR=", "), "Unknown") AS ?products)
  (COALESCE(SAMPLE(?descTextRaw), "Unknown") AS ?description)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabelRaw . }
  OPTIONAL { ?manufacturer sdk:hasNumberOfEmployees ?numRaw . }

  OPTIONAL {
    ?manufacturer sdk:hasCertificate ?cert .
    OPTIONAL { ?cert rdfs:label ?certLabel . }
  }

  OPTIONAL {
    ?manufacturer sdk:suppliesToIndustry ?industry .
    OPTIONAL { ?industry rdfs:label ?industryLabel . }
  }

  OPTIONAL {
    ?manufacturer sdk:hasProcessCapability ?proc .
    OPTIONAL { ?proc rdfs:label ?procLabel . }
  }

  OPTIONAL {
    ?manufacturer sdk:hasMaterialCapability ?mat .
    OPTIONAL { ?mat rdfs:label ?matLabel . }
  }

  OPTIONAL {
    ?manufacturer sdk:hasPrimaryNAICSClassifier ?naics .
    OPTIONAL { ?naics sdk:hasNAICSCodeValue ?naicsCodeRaw . }
    OPTIONAL { ?naics sdk:hasNAICSTextValue ?naicsTextRaw . }
  }

  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:locatedInCity ?cityRes .
      OPTIONAL { ?cityRes rdfs:label ?cityLabelRaw . }
      OPTIONAL {
        ?cityRes sdk:locatedInState ?stateRes .
        OPTIONAL { ?stateRes rdfs:label ?stateLabelRaw . }
      }
    }
    OPTIONAL {
      ?site sdk:hasZIPcode ?zipRes .
      OPTIONAL { ?zipRes sdk:hasIntegerValue ?zipRaw . }
    }
    OPTIONAL {
      ?site sdk:hasPostalAddress ?addr .
      OPTIONAL { ?addr iof-scro:hasTextValue ?addressRaw . }
    }
    OPTIONAL {
      ?site sdk:hasSpatialCoordinates ?coord .
      OPTIONAL { ?coord sdk:hasLatitudeValue ?latRaw . }
      OPTIONAL { ?coord sdk:hasLongitudeValue ?lonRaw . }
    }
  }

  OPTIONAL {
    ?manufacturer sdk:manufactures ?product .
    OPTIONAL { ?product rdfs:label ?productLabel . }
  }

  OPTIONAL {
    ?manufacturer iof-core:describedBy ?desc .
    OPTIONAL { ?desc iof-scro:hasTextValue ?descTextRaw . }
  }
}
GROUP BY ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasProcessCapability ?cap .
  ?cap a ?capClass .
  ?capClass rdfs:subClassOf* sdk:MachiningCapability .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state ?stateLabel ?manufacturer ?manufacturerLabel ?productCount
WHERE {
  {
    SELECT ?state ?manufacturer (COUNT(DISTINCT ?prod) AS ?productCount)
    WHERE {
      ?manufacturer a iof-core:Manufacturer ;
                    sdk:organizationLocatedIn ?site ;
                    sdk:manufactures ?prod ;
                    sdk:hasCertificate ?cert .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
    }
    GROUP BY ?state ?manufacturer
  }
  {
    SELECT ?state (MAX(?cnt) AS ?maxCount)
    WHERE {
      SELECT ?state ?manufacturer (COUNT(DISTINCT ?prod) AS ?cnt)
      WHERE {
        ?manufacturer a iof-core:Manufacturer ;
                      sdk:organizationLocatedIn ?site ;
                      sdk:manufactures ?prod ;
                      sdk:hasCertificate ?cert .
        ?site sdk:locatedInCity ?city .
        ?city sdk:locatedInState ?state .
      }
      GROUP BY ?state ?manufacturer
    }
    GROUP BY ?state
  }
  FILTER(?productCount = ?maxCount)
  OPTIONAL { ?state rdfs:label ?stateLabel . }
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
}
ORDER BY ?state ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?state ?stateLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  ?manufacturer (sdk:organizationLocatedIn/sdk:locatedInCity/sdk:locatedInState | sdk:locatedInState) ?state .
  ?state a sdk:State .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel }
  OPTIONAL { ?state rdfs:label ?stateLabel }
}
